      name: "陰イオン＋非イオン界面活性剤",
      description: "陰イオン（アニオン）と非イオン（ノニオン）という性質の異なる2種類の界面活性剤を配合した、いわゆる『複合型展着剤』です。1剤で付着性・展着性・湿展性をバランスよく発揮できる汎用性の高さが最大の特長で、家庭園芸から専業農家まで幅広く使われています。\n\n代表的な製品には「ダイン」があり、園芸用展着剤として最も知名度が高い製品の一つです。価格も手頃で入手しやすく、初めて展着剤を使う方にもおすすめできます。",
      effect: "2種類の界面活性剤がそれぞれの長所を補い合い、以下の効果を同時に発揮します。\n\n・付着力（陰イオン成分）：薬液を植物体表面にしっかり「くっつける」力。風で飛散しにくく、散布効率を高めます\n・展着力（非イオン成分）：薬液を薄く均一に「広げる」力。少量の薬液で葉全体をカバーでき、散布ムラを防ぎます\n・湿展力：乾いた葉の表面を「濡らす」力。撥水性のある葉でも薬液が水玉にならずに広がります\n\n特にムラのない均一な散布が求められる殺菌剤（マンネブダイセン、オーソサイド等）との組み合わせで効果を発揮します。耐雨性もエーテル型と同等以上で、散布後30分程度で乾けば小雨程度なら薬効が維持されます。",
      usageNote: "【混用性】大半の殺菌剤・殺虫剤と混用できますが、以下の組み合わせには注意してください。\n・石灰硫黄合剤やボルドー液など強アルカリ性の薬剤 → 界面活性剤が失活し効果が低下します\n・陽イオン（カチオン）系展着剤 → 凝固・沈殿（オリ）が生じるため絶対に混ぜないでください\n\n【調合順序】タンクミックスの際は「水→農薬→展着剤」の順に入れてください。展着剤を最後に加えることで泡立ちを抑え、均一に混ざります。\n\n【希釈倍率】一般的には1,000〜3,000倍（ダインの場合）。製品ラベルの指示に従ってください。\n\n【盆栽での使い方】通常の殺菌剤・殺虫剤散布の「とりあえず加える1本」として最適です。特別な理由がなければまずこのタイプを選んでおけば間違いありません。コスパも良く、小さなボトルで長期間使えます。",
      slug: "anionic-nonionic",
