      description: "プラスの電荷（カチオン）を帯びた特殊な界面活性剤を主成分とする展着剤です。植物の葉の表面はマイナスの電荷を帯びているため、プラスのカチオン展着剤は電気的に強く吸着し、通常の展着剤では実現できない『超耐雨性』を発揮します。\n\n降雨の多い梅雨時期や台風シーズンに、殺菌剤の効果を確実に維持したい場面で威力を発揮する「プロ仕様」の展着剤です。",
      effect: "電気的な吸着という独自のメカニズムにより、他のタイプとは異なる効果を発揮します。\n\n・超耐雨性：プラスとマイナスの電荷が引き合う力（静電吸着）で薬液を葉面に強固に定着させます。散布後1時間程度で乾燥すれば、50mm/h級の豪雨でも薬剤の流亡を大幅に抑制します\n・長期残効性：強い定着力により、通常の展着剤より2〜5日長く薬効が持続するとされています。散布間隔を延ばせるため、年間の散布回数削減につながります\n・付着均一性：電気的に引き合うため、重力に逆らって葉裏にも均一に付着しやすく、ハダニやアブラムシなど葉裏に潜む害虫への薬剤到達率が向上します\n\n梅雨時期の殺菌剤散布や、果樹・盆栽の黒星病・さび病の予防散布で特に効果を発揮します。",
      usageNote: "【最重要：混用禁止の組み合わせ】陽イオン（カチオン）は陰イオン（アニオン）と化学的に反発し、混ぜると凝固・沈殿（オリ）が生じます。以下との混用は絶対に避けてください。\n・陰イオン系展着剤（ダイン等の複合型含む）\n・陰イオン系の液体肥料\n・一部の乳剤（乳化剤がアニオン系の場合）\n\n不明な場合は、少量を別容器で混ぜてテスト（ジャーテスト）してから使用してください。\n\n【調合順序】必ず「水→農薬→展着剤」の順に加え、カチオン展着剤は最後に投入してください。先に入れると農薬の乳化が不安定になることがあります。\n\n【濃度管理】カチオン系は吸着力が強い反面、高濃度では薬害のリスクがあります。ラベル指定の希釈倍率を厳守し、新芽や花への直接散布は避けてください。\n\n【盆栽での使い方】梅雨前の殺菌剤散布（トップジンM、ベンレート等）に加えると、雨に流されにくく予防効果が長持ちします。年に数回の重要な防除タイミングで使うのが効果的です。",
      slug: "cationic",
