      description: "高純度の流動パラフィン（液体ワックス）を主成分とした、物理的な保護膜形成に特化した展着剤です。通常の展着剤が「薬液を植物に広げて付ける」ことを目的とするのに対し、パラフィン型は「油の膜で植物をコーティングする」という独自のアプローチを取ります。\n\n代表的な製品には「アビオンE」などがあります。マシン油乳剤の原理を応用した展着剤で、冬季のカイガラムシ防除やハダニ対策など、物理的防除を重視する場面で高い評価を受けています。",
      effect: "パラフィンの油膜が形成する物理的バリアにより、化学的な作用とは異なるユニークな効果を発揮します。\n\n・長時間保持：油膜が薬剤をゆっくり放出する『徐放効果』により、有効成分の効果持続時間が延長されます。特に保護殺菌剤（マンネブダイセン、オーソサイド等）との相性が抜群です\n・物理的防除の補助：パラフィンの油膜がカイガラムシやハダニの気門（呼吸穴）を塞ぎ、窒息させる効果があります。マシン油乳剤と同様の物理的防除メカニズムです\n・耐雨性：油膜は水に溶けないため、降雨による流亡に対して非常に強い耐性があります\n・紫外線遮蔽：油膜が紫外線を一部遮断し、紫外線に弱い薬剤（有機リン系など）の分解を遅らせる効果も期待できます\n\nカイガラムシが発生しやすい松柏類や柑橘類の盆栽で、冬季の防除に特に有効です。",
      usageNote: "【頻度に注意】パラフィンの皮膜は植物の気孔を一時的に塞ぐため、頻繁な連用（2週間以内の再散布）は避けてください。気孔の閉塞により光合成が阻害され、樹勢が弱る可能性があります。\n\n【温度制限】高温期（30℃以上）の使用は薬害リスクが高くなります。パラフィンの油膜がレンズ効果で葉焼けを引き起こすことがあるため、冬季〜早春（11月〜3月）の使用が最も安全で効果的です。\n\n【混用の注意】\n・マシン油乳剤との混用は油分過多になるため避けてください\n・石灰硫黄合剤との同時使用も薬害リスクが高いため禁止です\n・銅剤（ボルドー液等）との混用は問題ありません\n\n【盆栽での使い方】冬季（落葉後〜芽吹き前）のカイガラムシ・ハダニ防除に最適です。マシン油乳剤の代替または補助として、殺虫剤と混ぜて散布すると効果が高まります。生育期には濃度を薄めにし、頻繁な使用は控えてください。",
