      effect: "シリコーン特有の超低表面張力が生み出す効果は、従来の展着剤とは次元が異なります。\n\n・超拡展性：1滴の薬液が通常の展着剤の3〜5倍の面積に広がります。葉の表面を薄く均一にコーティングし、散布ムラを大幅に削減します\n・葉裏浸透：超低表面張力により、毛じ（トリコーム）の隙間を通り抜けて葉裏まで薬液が到達します。ハダニ・アブラムシ・コナジラミなど葉裏に棲む害虫への到達率が飛躍的に向上します\n・気孔浸透：植物の気孔（直径10〜30μm）を通じて薬液が内部に浸透し、浸透移行性薬剤の吸収効率を大幅に高めます\n・少量散布：従来の展着剤の半分以下の薬液量で同等以上の防除効果が得られるため、散布時間と薬剤コストを削減できます\n\n盆栽の密な樹冠内部や、針葉の間に潜む害虫への薬剤到達に特に威力を発揮します。",
